/* eslint-disable @angular-eslint/no-output-on-prefix */
declare const window: any;

import { Component, EventEmitter, Inject, Input, LOCALE_ID, OnChanges, OnDestroy, OnInit, Output, SimpleChanges, ViewChild } from '@angular/core';
import { HelperService, LookupService } from 'src/app/shared/services';
import { FormItem } from 'src/app/shared/models/form-config.model';
import { formatDate, formatNumber } from '@angular/common';
import { DxFormComponent } from 'devextreme-angular/ui/form';
import { BehaviorSubject, combineLatest, Observable, Subject } from 'rxjs';
import { auditTime, takeUntil } from 'rxjs/operators';
import { LookupOption } from '../../models/lookup.model';

type LookupKey =
  | 'hangHoas'
  | 'lienHes'
  | 'sanPhams'
  | 'khos'
  | 'khachHangs'
  | 'dvVanChuyens';

@Component({
  selector: 'app-dynamic-form',
  templateUrl: 'dynamic-form.component.html',
  styleUrls: ['dynamic-form.component.scss']
})
export class DyanmicFormComponent implements OnInit, OnDestroy, OnChanges {

  @Input() readOnlyAllFields: boolean = false;
  @Input() originalData: any = {};
  @Input() formData: any = {};
  @Input() formItems: FormItem[] = []
  // Output: emit data khi user change
  @Output() onFormDataChange = new EventEmitter<any>();

  // cache lists
  private lookupCache: Record<string, any[]> = {
    hangHoas: [],
    lienHes: [],
    sanPhams: [],
    khos: [],
    khachHangs: [],
    dvVanChuyens: [],
  };

  // cấu hình hiển thị/value mặc định cho từng lookup
  private lookupMeta: Record<LookupKey, { valueExpr: string; displayExpr: string }> = {
    hangHoas: { valueExpr: 'id', displayExpr: 'ten' },
    lienHes: { valueExpr: 'id', displayExpr: 'ten' },
    sanPhams: { valueExpr: 'id', displayExpr: 'ten' },
    khos: { valueExpr: 'id', displayExpr: 'ten' },
    khachHangs: { valueExpr: 'id', displayExpr: 'ten' },
    dvVanChuyens: { valueExpr: 'id', displayExpr: 'ten' },
  };

  // streams từ lookupService (như bạn gửi)
  hangHoas$ = this.lookupService.hangHoas.asObservable();
  lienHes$ = this.lookupService.lienHes.asObservable();
  sanPhams$ = this.lookupService.sanPhams.asObservable();
  khos$ = this.lookupService.khos.asObservable();
  khachHangs$ = this.lookupService.khachHangs.asObservable();
  dvVanChuyens$ = this.lookupService.dvVanChuyens.asObservable();

  @ViewChild(DxFormComponent, { static: false }) dxForm?: DxFormComponent;
  @ViewChild('detailForm') detailFormComp!: DyanmicFormComponent;

  localFormData: any = {};
  items: any[] = [];
  ready = false;

  // internal streams (để cover input đổi liên tục)
  private items$ = new BehaviorSubject<FormItem[]>([]);
  private data$ = new BehaviorSubject<any>({});
  private destroy$ = new Subject<void>();

  private silentUpdate = false;

  // ===== State để survive rename =====
  // map stableKey -> current dataField (theo schema mới nhất)
  private keyToField = new Map<string, string>();
  private prevKeyToField = new Map<string, string>();

  // baseline value tại thời điểm rebuild (để so changed)
  private baselineByKey = new Map<string, any>();

  // changed flags theo stableKey (không theo dataField)
  private changedByKey = new Map<string, boolean>();

  constructor(private lookupService: LookupService, @Inject(LOCALE_ID) public ngLocale: string) { }
  getValue() {
    return { ...HelperService.cloneObjectInfo(this.localFormData) };
  }

  validate() {
    return this.dxForm?.instance?.validate();
  }

  ngOnInit() {
    combineLatest([this.items$, this.data$]).pipe(
      auditTime(0),
      takeUntil(this.destroy$)
    ).subscribe(([items, data]) => {
      this.formItems = items || [];
      this.formData = data || {};
      this.rebuildForm();
    });

    // init first
    this.items$.next(this.formItems || []);
    this.data$.next(this.formData || {});

    this.bindLookupStreams();
  }
  private bindLookupStreams() {
    const registry: Array<[LookupKey, Observable<any[]>]> = [
      ['hangHoas', this.hangHoas$],
      ['lienHes', this.lienHes$],
      ['sanPhams', this.sanPhams$],
      ['khos', this.khos$],
      ['khachHangs', this.khachHangs$],
      ['dvVanChuyens', this.dvVanChuyens$],
    ];

    for (const [key, stream] of registry) {
      stream.pipe(takeUntil(this.destroy$)).subscribe(list => {
        this.lookupCache[key] = list || [];
        this.rebuildItemsOnly(); // chỉ refresh items để selectbox nhận list mới
      });
    }
  }

  private rebuildItemsOnly() {
    // nếu form chưa ready thì thôi (đang rebuild full)
    if (!this.ready) return;

    this.items = this.buildDxItems(this.formItems);
    // optional
    setTimeout(() => this.dxForm?.instance?.repaint(), 0);
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }
  ngOnChanges(changes: SimpleChanges): void {

    if (changes['formItems']) this.items$.next(this.formItems || []);
    if (changes['formData']) this.data$.next(this.formData || {});
  }
  private silent(fn: () => void) {
    this.silentUpdate = true;
    try {
      fn();
    } finally {
      // giữ silent qua ít nhất 1 microtask + 1 frame để dxForm apply xong rồi mới nhả
      Promise.resolve().then(() => {
        requestAnimationFrame(() => {
          this.silentUpdate = false;
        });
      });
    }
  }

  private rebuildForm() {
    // 1) build mapping stableKey -> dataField (new schema)
    this.prevKeyToField = new Map(this.keyToField);
    this.keyToField = this.collectKeyToField(this.formItems);

    // 2) migrate values from old field name -> new field name
    const normalized = this.migrateDataBySchema(this.formData || {}, this.formItems);

    // 3) build dx items
    const newItems = this.buildDxItems(this.formItems);

    // IMPORTANT: set items before formData
    this.ready = false;
    this.items = newItems;

    this.silent(() => {
      this.localFormData = { ...normalized };
      // build baseline + changed flags (reset theo schema hiện tại)
      this.buildBaselineAndChanged(this.localFormData, this.formItems);
    });

    // destroy/recreate dxForm để tránh giữ editor cũ
    Promise.resolve().then(() => {
      this.ready = true;
      setTimeout(() => this.dxForm?.instance?.repaint(), 0);
    });
  }
  onFieldDataChanged(e: any) {
    if (this.silentUpdate) return;
    console.log(`before lock ${e?.dataField}: ${e?.value}`);

    const field = e?.dataField as string;
    const value = e?.value;

    if (!field) return;

    console.log(`after lock ${field}: ${value}`);
    // update local data IN-PLACE (không đổi reference)
    if (!this.localFormData) this.localFormData = {};
    this.localFormData[field] = value;

    // mark changed theo stableKey
    const key = this.fieldKeyByDataField(field, this.formItems);
    if (key) {
      const base = this.baselineByKey.get(key);
      const isChanged = !this.deepEqual(base, value);
      this.changedByKey.set(key, isChanged);
      console.log(`after lock isChanged:${isChanged} ${field}: ${value}`);
      // ✅ update cssClass đúng item, không rebuild items
      const cls = this.getItemCssClass(key);
      // vì bạn set item.name = key, nên itemOption(key, ...) thường work cả trong group/tab
      this.dxForm?.instance?.itemOption(key, 'cssClass', cls);
    }

    // emit 1 lần từ đây
    const emitted = { ...(this.formData || {}), ...(this.localFormData || {}) };
    this.onFormDataChange.emit(emitted);
  }


  private getLookupKey(x: FormItem): string | null {
    // nếu schema có sẵn
    if ((x as any).lookupKey) return (x as any).lookupKey;

    // fallback theo stable key/name/roleKey
    const k = this.stableKeyOf(x);
    const map: Record<string, string> = {
      hangHoas: 'hangHoas',
      lienHes: 'lienHes',
      sanPhams: 'sanPhams',
      khos: 'khos',
      khachHangs: 'khachHangs',
      dvVanChuyens: 'dvVanChuyens',
    };
    return map[k] || null;
  }

  // ===================== Build Dx Items =====================
  private buildDxItems(items: FormItem[]) {
    const mapItem = (x: FormItem): any => {
      const isGroup = x.itemType === 'group' || x.itemType === 'tabbed';
      const isEmpty = x.itemType === 'empty';

      const base: any = {
        itemType: x.itemType,
        colSpan: x.colSpan,
        visible: x.visible !== false,
      };

      if (isEmpty) return { ...base };

      if (isGroup) {
        return {
          ...base,
          caption: x.label,
          // optional: nếu bạn có responsive trong group
          // colCountByScreen: (x as any).colCountByScreen,
          // colCount: (x as any).colCount,
          items: (x.items || []).map(mapItem),
        };
      }

      const key = this.stableKeyOf(x);

      // ===== Lookup SelectBox handling =====
      const lookupKey = this.getLookupKey?.(x) ? this.getLookupKey(x) : null; // 'hangHoas' | ...
      const isLookup = !!lookupKey;

      const readOnly = x.readOnly === true || this.readOnlyAllFields;

      // value/display expr: ưu tiên override trong schema
      const valueExpr =
        (x as any).lookupValueExpr ||
        (lookupKey ? this.lookupMeta?.[lookupKey]?.valueExpr : null) ||
        'id';

      const displayExpr =
        (x as any).lookupDisplayExpr ||
        (lookupKey ? this.lookupMeta?.[lookupKey]?.displayExpr : null) ||
        'name';

      // editorType: nếu lookup thì ép dxSelectBox
      const editorType = isLookup ? 'dxSelectBox' : x.editorType;

      // editorOptions gốc
      const editorOptions: any = {
        ...(x.editorOptions || {}),
        readOnly,
      };

      if (isLookup) {
        editorOptions.dataSource = this.lookupCache?.[lookupKey!] || [];
        editorOptions.valueExpr = editorOptions.valueExpr ?? valueExpr;
        editorOptions.displayExpr = editorOptions.displayExpr ?? displayExpr;
        editorOptions.searchEnabled = editorOptions.searchEnabled ?? true;
        editorOptions.showClearButton = editorOptions.showClearButton ?? true;

        // IMPORTANT: KHÔNG emit ở đây nữa, chỉ updateData để dxForm tự fire onFieldDataChanged
        const userOnValueChanged = editorOptions.onValueChanged;

        editorOptions.onValueChanged = (e: any) => {
          if (readOnly) return;

          // ✅ CHỐT CHẶN: nếu value không đổi thì thôi (tránh loop do re-apply option)
          const prev = this.localFormData?.[x.dataField];
          if (this.deepEqual(prev, e?.value)) return;

          // 1) báo dxForm cập nhật field (sẽ trigger onFieldDataChanged)
          this.dxForm?.instance?.updateData(x.dataField, e.value);

          // 2) lưu text hiển thị vào field__Text (nếu bạn dùng)
          const textKey = `${x.dataField}__Text`;
          const text = e?.component?.option?.('text');

          if (!this.localFormData) this.localFormData = {};
          this.localFormData[x.dataField] = e.value;
          if (text != null) this.localFormData[textKey] = text;

          // 3) gọi handler custom nếu schema có
          if (typeof userOnValueChanged === 'function') {
            userOnValueChanged(e);
          }

          // ❌ KHÔNG emit ở đây nữa (emit sẽ xảy ra tại onFieldDataChanged)
        };
      }

      return {
        ...base,
        name: key, // tiện debug/find
        dataField: x.dataField,
        label: { text: this.labelWithOld(x.dataField, x.label) || x.dataField },
        editorType,
        template: x.template,
        validationRules: x.validationRules?.length ? x.validationRules : undefined,
        cssClass: this.getItemCssClass(key),
        editorOptions,
      };
    };

    return (items || []).map(mapItem);
  }


  private getItemCssClass(stableKey: string) {
    const cls: string[] = [];
    console.log(stableKey);
    const isChanged = this.isChanged(stableKey);
    if (stableKey && (this.changedByKey.get(stableKey) || isChanged)) cls.push('changed-field');
    return cls.join(' ');
  }
  private isChanged(field: string): boolean {
    const current = this.formData ? this.formData[field] : undefined;
    const old = this.originalData ? this.originalData[field] : undefined;
    console.log({
      current, old
    })
    return !this.deepEqual(current, old);
  }

  // ===================== Schema Helpers =====================

  private stableKeyOf(x: FormItem): string {
    return x.key || x.name || x.roleKey || x.dataField;
  }

  private collectKeyToField(items: FormItem[]) {
    const m = new Map<string, string>();
    const walk = (arr: FormItem[]) => {
      for (const it of arr || []) {
        if (it.itemType === 'group' || it.itemType === 'tabbed') {
          walk(it.items || []);
        } else if (it.itemType !== 'empty') {
          m.set(this.stableKeyOf(it), it.dataField);
        }
      }
    };
    walk(items || []);
    return m;
  }

  // dataField -> stableKey (để mark changed)
  private fieldKeyByDataField(dataField: string, items: FormItem[]): string | null {
    let found: string | null = null;
    const walk = (arr: FormItem[]) => {
      for (const it of arr || []) {
        if (found) return;
        if (it.itemType === 'group' || it.itemType === 'tabbed') {
          walk(it.items || []);
        } else if (it.itemType !== 'empty') {
          if (it.dataField === dataField) found = this.stableKeyOf(it);
        }
      }
    };
    walk(items || []);
    return found;
  }

  // ===================== Migrate + Baseline =====================

  private migrateDataBySchema(input: any, items: FormItem[]) {
    const data = { ...(input || {}) };

    // migrate theo prevKeyToField -> keyToField (rename dataField)
    for (const [key, newField] of this.keyToField.entries()) {
      const oldField = this.prevKeyToField.get(key);

      // ưu tiên oldDataField nếu server có gửi
      const forcedOld = this.findOldDataFieldByKey(items, key);
      const fromField = forcedOld || oldField;

      if (fromField && fromField !== newField) {
        if (data[fromField] != null && data[newField] == null) {
          data[newField] = data[fromField];
        }
        // migrate __Text nếu bạn dùng kiểu field__Text
        const oldText = `${fromField}__Text`;
        const newText = `${newField}__Text`;
        if (data[oldText] != null && data[newText] == null) {
          data[newText] = data[oldText];
        }
      }
    }

    return data;
  }

  private findOldDataFieldByKey(items: FormItem[], key: string): string | null {
    let result: string | null = null;
    const walk = (arr: FormItem[]) => {
      for (const it of arr || []) {
        if (result) return;
        if (it.itemType === 'group' || it.itemType === 'tabbed') walk(it.items || []);
        else if (it.itemType !== 'empty') {
          if (this.stableKeyOf(it) === key && it.oldDataField) result = it.oldDataField;
        }
      }
    };
    walk(items || []);
    return result;
  }

  private buildBaselineAndChanged(data: any, items: FormItem[]) {
    // baseline = snapshot dữ liệu tại lúc rebuild
    this.baselineByKey.clear();

    const walk = (arr: FormItem[]) => {
      for (const it of arr || []) {
        if (it.itemType === 'group' || it.itemType === 'tabbed') {
          walk(it.items || []);
        } else if (it.itemType !== 'empty') {
          const key = this.stableKeyOf(it);
          const v = data?.[it.dataField];
          this.baselineByKey.set(key, this.cloneLite(v));

          // reset changed theo baseline (giữ map nhưng set lại đúng schema)
          this.changedByKey.set(key, false);
        }
      }
    };
    walk(items || []);
  }

  // ===================== Utils =====================

  private deepEqual(a: any, b: any) {
    // đủ dùng cho primitive/date/json nhỏ
    if (a === b) return true;
    // Date compare
    if (a instanceof Date || b instanceof Date) {
      const ta = a instanceof Date ? a.getTime() : new Date(a).getTime();
      const tb = b instanceof Date ? b.getTime() : new Date(b).getTime();
      return ta === tb;
    }
    // fallback JSON
    try { return JSON.stringify(a) === JSON.stringify(b); }
    catch { return false; }
  }

  private cloneLite(v: any) {
    if (v == null) return v;
    if (v instanceof Date) return new Date(v.getTime());
    if (typeof v === 'object') {
      try { return JSON.parse(JSON.stringify(v)); } catch { return v; }
    }
    return v;
  }


  labelWithOld(field, label: string): string {
    const old = this.displayOldValue(field);
    return `${label}:\n(${old})`;
  }


  private displayOldValue(field): string {
    const value = this.originalData ? this.originalData[field] : undefined;
    const isIsoDateTime = HelperService.isIsoDateTime(value as any);

    if (value instanceof Date || isIsoDateTime) {
      const formattedDate = formatDate(value, 'dd/MM/yyyy', this.ngLocale);
      return formattedDate;
    }
    if (typeof value === 'number') {
      return formatNumber(value, this.ngLocale);
    }
    if (typeof value === 'string') {
      return String(value);
    }
    return '';
  }

  normalizeUrl(url: string): string {
    const u = (url ?? '').trim();
    if (!u) return '';
    return /^https?:\/\//i.test(u) ? u : `https://${u}`;
  }

  openUrl(url: string) {
    const u = this.normalizeUrl(url);
    if (!u) return;
    window.open(u, '_blank', 'noopener');
  }

  async copyToClipboard(text: string) {
    const t = (text ?? '').trim();
    if (!t) return;

    // ưu tiên clipboard API
    if (navigator.clipboard?.writeText) {
      try { await navigator.clipboard.writeText(t); return; } catch { }
    }

    // fallback (deprecated nhưng cứu cháy khi http/intranet)
    const ta = document.createElement('textarea');
    ta.value = t;
    ta.style.position = 'fixed';
    ta.style.left = '-9999px';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } finally { document.body.removeChild(ta); }
  }


}

