import { Component, EventEmitter, Input, Output } from '@angular/core';
import { ChangeRequestBasicSearchForm } from '../change-request-basic.model';
import { LookupService } from 'src/app/shared/services';

@Component({
  selector: 'app-change-request-basic-search-panel',
  templateUrl: './change-request-basic-search-panel.component.html'
})
export class ChangeRequestBasicSearchPanelComponent {
  @Input() searchForm: ChangeRequestBasicSearchForm;
  @Output() search = new EventEmitter<void>();
  @Output() reset = new EventEmitter<void>();
  contextKeys$ = this.lookupService.contextKeys.asObservable();

  constructor(private lookupService: LookupService){}

  onSearchClick(): void {
    this.search.emit();
  }

  onResetClick(): void {
    this.reset.emit();
  }
}
