import { Injectable } from '@angular/core';
import { from, Observable, throwError } from 'rxjs';
import { catchError, timeout } from 'rxjs/operators';

export interface ApiCallOptions {
  timeoutMs?: number;
}

@Injectable({ providedIn: 'root' })
export class ApiGatewayService {
  private callAPI(functionName: string, payload: any): Promise<any> {
    const fn = (window as any)?._appScriptApi;
    if (typeof fn !== 'function') {
      return Promise.reject(new Error('callAPI is not available on window'));
    }
    return fn(functionName, payload);
  }

  call$<T = any>(
    functionName: string,
    payload: any,
    options: ApiCallOptions = {}
  ): Observable<T> {
    const base$ = from(this.callAPI(functionName, payload)) as Observable<T>;

    const withTimeout$ = options.timeoutMs
      ? base$.pipe(timeout(options.timeoutMs))
      : base$;

    return withTimeout$.pipe(
      catchError((err) => throwError(() => err))
    );
  }

  callAsync<T = any>(functionName: string, payload: any): Promise<T> {
    return this.callAPI(functionName, payload) as Promise<T>;
  }
}
