import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { CommonModule } from '@angular/common';
import {
  DxDataGridModule,
  DxFormModule,
  DxButtonModule,
  DxPopupModule,
  DxSelectBoxModule,
  DxDateBoxModule,
  DxToolbarModule,
  DxTextBoxModule,
  DxTextAreaModule,
  DxNumberBoxModule,
  DxCheckBoxModule,
  DxTabPanelModule,
  DxDropDownBoxModule,
  DxDropDownButtonModule,
  DxScrollViewModule
} from 'devextreme-angular';
import { DyanmicFormComponent, LoginFormComponent } from './shared/components';
import { AuthGuardService } from './shared/services';
import { HomeComponent } from './pages/home/home.component';
import { ProfileComponent } from './pages/profile/profile.component';
import { OrderMasterComponent } from './pages/order-master/order-master.component';
import { OrderMasterSearchPanelComponent } from './pages/order-master/components/order-master-search-panel.component';
import { OrderMasterPopupComponent } from './pages/order-master/components/order-master-popup.component';
import { OrderDetailComponent } from './pages/order-detail/order-detail.component';
import { OrderDetailSearchPanelComponent } from './pages/order-detail/components/order-detail-search-panel.component';
import { OrderDetailPopupComponent } from './shared/components/order-detail/order-detail-popup.component';
import { ChangeRequestBasicComponent, ChangeRequestBasicPopupComponent, ChangeRequestBasicSearchPanelComponent } from './pages/change-request-basic';

const routes: Routes = [
  {
    path: 'change-request-basic',
    component: ChangeRequestBasicComponent,
    canActivate: [AuthGuardService]
  },
  {
    path: 'profile',
    component: ProfileComponent,
    canActivate: [AuthGuardService]
  },
  {
    path: 'home',
    component: HomeComponent,
    canActivate: [AuthGuardService]
  },
  {
    path: 'login-form',
    component: LoginFormComponent,
    canActivate: [AuthGuardService]
  },
  {
    path: '**',
    redirectTo: 'home',
    canActivate: [AuthGuardService]
  }
];

@NgModule({
  imports: [
    CommonModule,
    RouterModule.forRoot(routes),
    DxDataGridModule,
    DxFormModule,
    DxButtonModule,
    DxPopupModule,
    DxFormModule,
    DxSelectBoxModule,
    DxDateBoxModule,
    DxToolbarModule,
    DxTextBoxModule,
    DxTextAreaModule,
    DxNumberBoxModule,
    DxCheckBoxModule,
    DxTabPanelModule,
    DxDropDownBoxModule,
    DxDropDownButtonModule,
    DxScrollViewModule,
  ],
  providers: [AuthGuardService],
  exports: [
    HomeComponent,
    ProfileComponent,
    OrderMasterComponent,
    OrderMasterSearchPanelComponent,
    OrderMasterPopupComponent,
    OrderDetailComponent,
    OrderDetailSearchPanelComponent,
    OrderDetailPopupComponent,
    ChangeRequestBasicComponent,
    ChangeRequestBasicPopupComponent,
    ChangeRequestBasicSearchPanelComponent
  ],
  declarations: [
    HomeComponent,
    ProfileComponent,
    OrderMasterComponent,
    OrderMasterSearchPanelComponent,
    OrderMasterPopupComponent,
    OrderDetailComponent,
    OrderDetailSearchPanelComponent,
    OrderDetailPopupComponent,
    ChangeRequestBasicComponent,
    ChangeRequestBasicPopupComponent,
    ChangeRequestBasicSearchPanelComponent,
    DyanmicFormComponent
  ]
})
export class AppRoutingModule { }
