import { Injectable } from '@angular/core';
import { HelperService } from './helper.service';

@Injectable({ providedIn: 'root' })
export class AppInfoService {
  constructor() { }

  public get isProduction() {
    return (window as any).__env?.production === true;
  }

  public get title() {
    return 'DV IT';
  }
  public get yearCopyRight() {
    return new Date().getFullYear();
  }
  public get currentUserInfo(): EnvConfig["currentUser"] {
    const jsonString = (window as any).__env?.currentUser;
    if (!jsonString) {
      return null;
    }
    if (typeof jsonString === 'object') {
      return HelperService.cloneObjectInfo(jsonString) as EnvConfig["currentUser"];
    }
    return jsonString ? JSON.parse(jsonString) as EnvConfig["currentUser"] : null;
  }
  public get initData() {
    const jsonString = (window as any).__env?.initData;
    if (!jsonString) {
      return null;
    }
    if (typeof jsonString === 'object') {
      return HelperService.cloneObjectInfo(jsonString) as InitData;
    }

    return jsonString ? JSON.parse(jsonString) as InitData : null;
  }

  public get newChangeRequestData(): InitData["newChangeRequestData"] {
    const initData = this.initData;
    if (!initData) {
      throw new Error('Init data is not available');
    }
    return initData.newChangeRequestData;
  }
}

export interface EnvConfig {
  production: boolean;
  apiBaseUrl: string;
  initData: InitData;
  currentUser: {
    userId: string;
    userName: string;
    fullName: string;
    email: string;
    permissions: any[];
  };
}

export interface InitData {

  newChangeRequestData?: {
    contextKey: string;
    changeType: 'create' | 'update' | 'delete';
    objectRowIndexsString: string,
    objectIdsString: string,
  }
}
