// base-lookup.service.ts
import { get as idbGet, set as idbSet, del as idbDel } from 'idb-keyval';
import { from, Observable } from 'rxjs';

export class BaseLookupService<T> {
  private cachePromise?: Promise<T[]>;
  private backendVersion = '';
  private autoRetryTimer?: any;

  constructor(
    private functionName: string,
    private payload?: any,
    private ttlMs: number = 24 * 60 * 60 * 1000, // 24h
    private tenantKey?: string,
    private retryCount: number = 2,
    private autoRetryIntervalMs: number = 5 * 60 * 1000 // 5 phút
  ) {}

  private get storageKey(): string {
    return `LOOKUP_CACHE_${this.tenantKey ?? 'GLOBAL'}_${this.functionName}`;
  }

  /** --- Promise API --- */
  get(): Promise<T[]> {
    if (this.cachePromise) return this.cachePromise;

    this.cachePromise = this.getFromCache().then(localData => {
      if (localData && !this.backendVersionChanged(localData)) return localData;

      return this.callBackendWithRetry(this.retryCount).catch(err => {
        console.warn(`[LookupService] Initial load failed for ${this.functionName}, scheduling auto retry.`);
        this.scheduleAutoRetry();
        return this.getFromCache().then(fallback => fallback ?? []);
      });
    });

    return this.cachePromise;
  }

  /** --- Observable API for DevExtreme async pipe --- */
  asObservable(): Observable<T[]> {
    return from(this.get());
  }

  /** --- Manual refresh --- */
  refresh(): void {
    this.cachePromise = undefined;
    this.clearStorage();
  }

  /** --- Internal: memory → IndexedDB → localStorage --- */
  private async getFromCache(): Promise<T[] | null> {
    try {
      const idbCache: { timestamp: number; data: T[]; version?: string } | undefined = await idbGet(this.storageKey);
      if (idbCache && Date.now() - idbCache.timestamp <= this.ttlMs) {
        this.backendVersion = idbCache.version ?? '';
        return idbCache.data;
      }
    } catch {}

    try {
      const json = localStorage.getItem(this.storageKey);
      if (json) {
        const obj: { timestamp: number; data: T[]; version?: string } = JSON.parse(json);
        if (Date.now() - obj.timestamp <= this.ttlMs) {
          this.backendVersion = obj.version ?? '';
          return obj.data;
        }
      }
    } catch {}

    return null;
  }

  private async saveToCache(data: T[], version?: string) {
    const obj = { timestamp: Date.now(), data, version };
    try { await idbSet(this.storageKey, obj); } catch {
      try { localStorage.setItem(this.storageKey, JSON.stringify(obj)); } catch {}
    }
  }

  private async clearStorage(): Promise<void> {
    try { await idbDel(this.storageKey); } catch {}
    try { localStorage.removeItem(this.storageKey); } catch {}
  }

  /** --- Retry logic --- */
  private async callBackendWithRetry(retries: number): Promise<T[]> {
    for (let i = 0; i <= retries; i++) {
      try {
        return await this.callBackend();
      } catch (err) {
        console.warn(`[LookupService] Attempt ${i + 1} failed for ${this.functionName}:`, err);
        if (i === retries) throw err;
      }
    }
    return [];
  }

  /** --- Call backend safely --- */
  private async callBackend(): Promise<T[]> {
    if (!(window as any)._appScriptApi) {
      throw new Error('_appScriptApi is not defined');
    }

    const res = await (window as any)._appScriptApi(this.functionName, this.payload);
    const version = res?.version ?? '';
    const data: T[] = Array.isArray(res) ? res : Array.isArray(res?.data) ? res.data : [];

    this.backendVersion = version;
    await this.saveToCache(data, version);

    return data;
  }

  /** --- Schedule auto retry if network fails --- */
  private scheduleAutoRetry(): void {
    if (this.autoRetryTimer) return; // đã có timer
    this.autoRetryTimer = setInterval(async () => {
      try {
        const data = await this.callBackendWithRetry(this.retryCount);
        if (data.length > 0) {
          clearInterval(this.autoRetryTimer);
          this.autoRetryTimer = undefined;
          this.cachePromise = Promise.resolve(data); // cập nhật cachePromise cho async pipe
        }
      } catch {
        // ignore, sẽ thử lại lần sau
      }
    }, this.autoRetryIntervalMs);
  }

  /** --- check backend version change */
  private backendVersionChanged(cachedData: any): boolean {
    return cachedData?.version && this.backendVersion && cachedData.version !== this.backendVersion;
  }
}
