import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

@Injectable({ providedIn: 'root' })
export class AppStateService {
  private isStartChangeRequestFromGGSheet$ = new BehaviorSubject<boolean>(false);
  isStartChangeRequestFromGGSheetObs$ = this.isStartChangeRequestFromGGSheet$.asObservable();

  set_isStartChangeRequestFromGGSheet(v: boolean) { this.isStartChangeRequestFromGGSheet$.next(v); }
  get_isStartChangeRequestFromGGSheet() { return this.isStartChangeRequestFromGGSheet$.value; }
}
