import { Injectable } from '@angular/core';
import { BehaviorSubject, defer, Observable } from 'rxjs';
import { finalize } from 'rxjs/operators';

@Injectable({ providedIn: 'root' })
export class LoadingService {
  private counter = 0;
  private readonly loadingSubject = new BehaviorSubject<boolean>(false);
  readonly loading$ = this.loadingSubject.asObservable();

  show(): void {
    this.counter += 1;
    if (!this.loadingSubject.value) {
      Promise.resolve().then(() => this.loadingSubject.next(true));
    }
  }

  hide(): void {
    if (this.counter > 0) this.counter -= 1;
    if (this.counter === 0 && this.loadingSubject.value) {
      Promise.resolve().then(() => this.loadingSubject.next(false));
    }
  }
  public async runWithLoading<T>(fn: () => Promise<T>): Promise<T> {
    this.show();
    try {
      return await fn();
    } finally {
      this.hide();
    }
  }
  // ✅ NEW: dùng cho Observable
  public runWithLoading$<T>(source$: Observable<T>): Observable<T> {
    return defer(() => {
      this.show();
      return source$.pipe(finalize(() => this.hide()));
    });
  }
}
